"""Thread-safe registry of connected WebSocket clients."""
from __future__ import annotations

import threading
from typing import Any


class ClientRegistry:
    """Maps client_id -> connection object, safe to touch from multiple threads."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._clients: dict[str, Any] = {}

    def add(self, client_id: str, connection: Any) -> None:
        with self._lock:
            self._clients[client_id] = connection

    def remove(self, client_id: str) -> None:
        with self._lock:
            self._clients.pop(client_id, None)

    def get(self, client_id: str) -> Any | None:
        with self._lock:
            return self._clients.get(client_id)

    def connections(self) -> list[Any]:
        with self._lock:
            return list(self._clients.values())

    def ids(self) -> list[str]:
        with self._lock:
            return list(self._clients.keys())

    def count(self) -> int:
        with self._lock:
            return len(self._clients)

    def __contains__(self, client_id: str) -> bool:
        with self._lock:
            return client_id in self._clients

"""JSON notification message parsing and construction.

Every message on the wire is `{type: str, payload: dict, timestamp: str}`
with `type` restricted to 'broadcast', 'direct', or 'system'.
"""
from __future__ import annotations

import json
from datetime import datetime, timezone
from typing import Any

VALID_TYPES = {"broadcast", "direct", "system"}


class InvalidMessage(ValueError):
    """Raised when a client sends something that doesn't match the message format."""


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def parse_message(raw: str) -> dict[str, Any]:
    try:
        data = json.loads(raw)
    except (json.JSONDecodeError, TypeError) as exc:
        raise InvalidMessage(f"invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise InvalidMessage("message must be a JSON object")

    msg_type = data.get("type")
    if msg_type not in VALID_TYPES:
        raise InvalidMessage(
            f"unsupported type {msg_type!r}; expected one of {sorted(VALID_TYPES)}"
        )

    payload = data.get("payload", {})
    if not isinstance(payload, dict):
        raise InvalidMessage("payload must be an object")

    timestamp = data.get("timestamp") or now_iso()
    if not isinstance(timestamp, str):
        raise InvalidMessage("timestamp must be a string")

    return {"type": msg_type, "payload": payload, "timestamp": timestamp}


def make_message(msg_type: str, payload: dict[str, Any], **extra: Any) -> dict[str, Any]:
    if msg_type not in VALID_TYPES:
        raise InvalidMessage(f"unsupported type {msg_type!r}")
    message: dict[str, Any] = {"type": msg_type, "payload": payload, "timestamp": now_iso()}
    message.update(extra)
    return message


def error_message(text: str) -> dict[str, Any]:
    return make_message("system", {"event": "error", "message": text})


def dumps(message: dict[str, Any]) -> str:
    return json.dumps(message)

import json

import pytest

from notification_server.messages import (
    InvalidMessage,
    error_message,
    make_message,
    parse_message,
)


def test_parse_valid_broadcast_message():
    raw = json.dumps({"type": "broadcast", "payload": {"text": "hi"}, "timestamp": "2026-01-01T00:00:00Z"})
    msg = parse_message(raw)
    assert msg == {"type": "broadcast", "payload": {"text": "hi"}, "timestamp": "2026-01-01T00:00:00Z"}


def test_parse_fills_in_missing_timestamp():
    raw = json.dumps({"type": "system", "payload": {}})
    msg = parse_message(raw)
    assert msg["timestamp"]


def test_parse_rejects_invalid_json():
    with pytest.raises(InvalidMessage):
        parse_message("not json")


def test_parse_rejects_non_object_json():
    with pytest.raises(InvalidMessage):
        parse_message(json.dumps([1, 2, 3]))


def test_parse_rejects_unsupported_type():
    with pytest.raises(InvalidMessage):
        parse_message(json.dumps({"type": "bogus", "payload": {}}))


def test_parse_rejects_non_object_payload():
    with pytest.raises(InvalidMessage):
        parse_message(json.dumps({"type": "broadcast", "payload": "nope"}))


@pytest.mark.parametrize("msg_type", ["broadcast", "direct", "system"])
def test_parse_accepts_all_valid_types(msg_type):
    raw = json.dumps({"type": msg_type, "payload": {}})
    msg = parse_message(raw)
    assert msg["type"] == msg_type


def test_make_message_rejects_unsupported_type():
    with pytest.raises(InvalidMessage):
        make_message("bogus", {})


def test_error_message_shape():
    err = error_message("boom")
    assert err["type"] == "system"
    assert err["payload"]["event"] == "error"
    assert err["payload"]["message"] == "boom"
